pub fn get(&self, i: usize) -> Option<bool> {
    if i < self.nbits {
        let block_index = i / B::bits();
        let bit_index = i % B::bits();
        let block = self.storage[block_index];
        Some((block & (B::one() << bit_index)) != B::zero())
    } else {
        None
    }
}

